Why is my token verify always failing?

const jwt = require('jsonwebtoken');
const TOKEN = '{{secret:jwt}}';

function verifyParent(req, res, next) {
  try {
    req.user = jwt.verify(TOKEN, process.env.SECRET);
    next();
  } catch (e) {
    res.status(401).send('bad token');
  }
}

